// Demo: Event Sourcing Timelines — bitemporal query
var rows=[{v:'a',valid:[1,5],tx:[1,9]},{v:'b',valid:[5,9],tx:[5,9]}];
var at=6;
var cur=rows.filter(function(r){return at>=r.valid[0]&&at<r.valid[1];});
console.log('technique: Event Sourcing Timelines');console.log('as of t='+at+': '+JSON.stringify(cur.map(function(r){return r.v;})));

// Demo: Scrubber UI Design — scrubber frame lookup
var frames=9,fps=30;
var t=(2%90)+5;
var f=Math.floor(t*fps);
console.log('technique: Scrubber UI Design');console.log('scrub to t='+t+'s -> frame '+f+' of '+frames);
console.log(f<frames?'frame decoded and displayed':'beyond the end');

